/* GreenBean Coffee — Shared Styles */
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,wght@0,300;0,400;0,500;0,600;0,700;1,400&family=Playfair+Display:wght@400;600;700&display=swap');

:root {
  --green: #00824A;
  --dark-forest: #32462F;
  --cream: #F3CEA1;
  --cream-light: #FDF6EC;
  --brown: #5C3D2E;
  --brown-light: #A0714F;
  --text: #1A1A1A;
  --text-muted: #6B6B6B;
  --white: #FFFFFF;
  --border: #E8E0D5;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.08);
  --shadow-md: 0 4px 20px rgba(0,0,0,0.12);
  --shadow-lg: 0 8px 40px rgba(0,0,0,0.16);
  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-full: 9999px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'DM Sans', system-ui, sans-serif;
  color: var(--text);
  background: var(--white);
  line-height: 1.6;
  font-size: 16px;
}

img { display: block; max-width: 100%; }
a { text-decoration: none; color: inherit; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
ul { list-style: none; }

/* ===== UTILITY ===== */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }

.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 12px 28px; border-radius: var(--radius-full);
  font-size: 15px; font-weight: 600; line-height: 1; transition: all 0.2s ease;
  white-space: nowrap;
}
.btn-primary { background: var(--green); color: var(--white); }
.btn-primary:hover { background: var(--dark-forest); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-secondary { background: var(--white); color: var(--dark-forest); border: 2px solid var(--dark-forest); }
.btn-secondary:hover { background: var(--dark-forest); color: var(--white); }
.btn-outline-white { background: transparent; color: var(--white); border: 2px solid var(--white); }
.btn-outline-white:hover { background: var(--white); color: var(--dark-forest); }
.btn-cream { background: var(--cream); color: var(--dark-forest); }
.btn-cream:hover { background: #e8b87a; }

/* ===== HEADER / NAV ===== */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: var(--dark-forest);
  box-shadow: var(--shadow-sm);
}
.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  height: 64px; padding: 0 24px; max-width: 1400px; margin: 0 auto;
}
.logo {
  display: flex; align-items: center; gap: 10px;
  font-family: 'Playfair Display', serif; font-size: 22px; font-weight: 700; color: var(--cream);
}
.logo-icon {
  width: 36px; height: 36px; background: var(--green); border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 18px;
}
.nav-primary { display: flex; align-items: center; gap: 4px; }
.nav-primary a {
  padding: 8px 16px; border-radius: var(--radius-full); color: var(--cream);
  font-size: 15px; font-weight: 500; transition: background 0.2s;
}
.nav-primary a:hover, .nav-primary a.active { background: rgba(243,206,161,0.15); }
.nav-actions { display: flex; align-items: center; gap: 10px; }
.nav-actions a {
  padding: 8px 18px; border-radius: var(--radius-full);
  font-size: 14px; font-weight: 600; transition: all 0.2s;
}
.btn-signin { color: var(--cream); border: 1.5px solid rgba(243,206,161,0.4); }
.btn-signin:hover { border-color: var(--cream); background: rgba(243,206,161,0.1); }
.btn-join { background: var(--green); color: var(--white); }
.btn-join:hover { background: #00a05c; }
.hamburger { display: none; flex-direction: column; gap: 5px; padding: 8px; }
.hamburger span { display: block; width: 22px; height: 2px; background: var(--cream); border-radius: 2px; }

/* ===== FOOTER ===== */
.site-footer { background: var(--dark-forest); color: var(--cream); padding: 60px 0 0; }
.footer-grid {
  display: grid; grid-template-columns: repeat(5, 1fr); gap: 32px;
  padding-bottom: 48px; border-bottom: 1px solid rgba(243,206,161,0.2);
}
.footer-col h4 {
  font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em;
  color: var(--cream); margin-bottom: 16px;
}
.footer-col a {
  display: block; font-size: 14px; color: rgba(243,206,161,0.7);
  padding: 4px 0; transition: color 0.2s;
}
.footer-col a:hover { color: var(--cream); }
.footer-bottom {
  display: flex; align-items: center; justify-content: space-between;
  padding: 24px 0; flex-wrap: wrap; gap: 16px;
}
.footer-bottom p { font-size: 13px; color: rgba(243,206,161,0.5); }
.footer-social { display: flex; gap: 12px; }
.footer-social a {
  width: 36px; height: 36px; border-radius: 50%; background: rgba(243,206,161,0.1);
  display: flex; align-items: center; justify-content: center;
  color: var(--cream); font-size: 16px; transition: background 0.2s;
}
.footer-social a:hover { background: var(--green); }
.footer-accordion-toggle { display: none; }

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 200;
  background: var(--dark-forest); color: var(--cream);
  padding: 20px 24px; box-shadow: 0 -4px 24px rgba(0,0,0,0.2);
  display: flex; align-items: center; justify-content: space-between; gap: 24px;
  flex-wrap: wrap;
}
.cookie-banner.hidden { display: none; }
.cookie-text h3 { font-size: 15px; font-weight: 700; margin-bottom: 4px; }
.cookie-text p { font-size: 13px; color: rgba(243,206,161,0.75); }
.cookie-actions { display: flex; gap: 10px; flex-shrink: 0; }
.cookie-actions button {
  padding: 10px 20px; border-radius: var(--radius-full);
  font-size: 14px; font-weight: 600; cursor: pointer; transition: all 0.2s;
}
.btn-cookie-settings { background: transparent; color: var(--cream); border: 1.5px solid rgba(243,206,161,0.4); }
.btn-cookie-settings:hover { border-color: var(--cream); }
.btn-cookie-agree { background: var(--green); color: var(--white); border: none; }
.btn-cookie-agree:hover { background: #00a05c; }

/* ===== PLACEHOLDER IMAGES ===== */
.img-placeholder {
  background: linear-gradient(135deg, var(--cream) 0%, #d4a574 50%, var(--brown-light) 100%);
  border-radius: var(--radius-md); overflow: hidden; position: relative;
  display: flex; align-items: center; justify-content: center;
}
.img-placeholder::after {
  content: '☕'; font-size: 48px; opacity: 0.3;
  position: absolute;
}
.img-placeholder.hero-img { min-height: 400px; border-radius: 0; }
.img-placeholder.card-img { height: 200px; }
.img-placeholder.tall-img { height: 320px; }
.img-placeholder.small-img { height: 140px; }
.img-placeholder.gift-img {
  background: linear-gradient(135deg, #00824A, #32462F);
  height: 180px; border-radius: var(--radius-sm);
}
.img-placeholder.gift-img::after { content: '🎁'; }
.img-placeholder.menu-img { height: 160px; }

/* ===== SECTION HEADERS ===== */
.section-tag {
  display: inline-block; font-size: 12px; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.1em;
  color: var(--green); margin-bottom: 8px;
}
.section-title {
  font-family: 'Playfair Display', serif; font-size: clamp(28px, 4vw, 42px);
  font-weight: 700; line-height: 1.2; color: var(--dark-forest); margin-bottom: 16px;
}
.section-body { font-size: 16px; color: var(--text-muted); line-height: 1.7; }

/* ===== PROMO CARDS ===== */
.promo-card {
  border-radius: var(--radius-lg); overflow: hidden;
  background: var(--cream-light); box-shadow: var(--shadow-sm);
  transition: transform 0.2s, box-shadow 0.2s;
}
.promo-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.promo-card-content { padding: 32px 28px; }

/* ===== TABS ===== */
.tabs-nav {
  display: flex; gap: 4px; overflow-x: auto;
  border-bottom: 2px solid var(--border); margin-bottom: 32px;
  scrollbar-width: none;
}
.tabs-nav::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 12px 20px; font-size: 15px; font-weight: 600;
  color: var(--text-muted); border-bottom: 3px solid transparent;
  margin-bottom: -2px; white-space: nowrap; transition: all 0.2s;
  background: none; border-top: none; border-left: none; border-right: none;
}
.tab-btn:hover { color: var(--green); }
.tab-btn.active { color: var(--green); border-bottom-color: var(--green); }
.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* ===== CAROUSEL ===== */
.carousel-wrapper { position: relative; }
.carousel-track-container { overflow: hidden; }
.carousel-track {
  display: flex; gap: 20px; transition: transform 0.35s cubic-bezier(0.25,0.46,0.45,0.94);
}
.carousel-controls {
  display: flex; align-items: center; justify-content: flex-end; gap: 8px; margin-top: 16px;
}
.carousel-btn {
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--dark-forest); color: var(--white);
  display: flex; align-items: center; justify-content: center;
  font-size: 18px; transition: all 0.2s; border: none; cursor: pointer;
}
.carousel-btn:hover { background: var(--green); transform: scale(1.05); }
.carousel-btn:disabled { background: var(--border); color: var(--text-muted); cursor: not-allowed; transform: none; }
.carousel-item { flex: 0 0 auto; }

/* ===== STAR ICON ===== */
.star { color: #F5A623; }

/* ===== BADGE ===== */
.badge {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 4px 12px; border-radius: var(--radius-full);
  font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em;
}
