.badge-gold { background: rgba(245,166,35,0.15); color: #B8860B; }
.badge-reserve { background: rgba(50,70,47,0.1); color: var(--dark-forest); }

/* ===== RESPONSIVE ===== */
@media (max-width: 900px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 0; }
  .footer-col { border-bottom: 1px solid rgba(243,206,161,0.15); }
  .footer-col h4 {
    padding: 16px 0; margin-bottom: 0; cursor: pointer;
    display: flex; justify-content: space-between; align-items: center;
  }
  .footer-col h4::after { content: '+'; font-size: 18px; }
  .footer-col.open h4::after { content: '−'; }
  .footer-col ul { display: none; padding-bottom: 16px; }
  .footer-col.open ul { display: block; }
}

@media (max-width: 768px) {
  .nav-primary, .nav-actions { display: none; }
  .hamburger { display: flex; }
  .nav-primary.mobile-open {
    display: flex; flex-direction: column;
    position: fixed; top: 64px; left: 0; right: 0; bottom: 0;
    background: var(--dark-forest); padding: 24px; z-index: 99;
    overflow-y: auto;
  }
  .nav-primary.mobile-open a { font-size: 20px; padding: 14px 16px; }
  .footer-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .btn { padding: 10px 20px; font-size: 14px; }
  .cookie-banner { flex-direction: column; align-items: flex-start; }
}

