<script>
  // Mobile nav
  document.getElementById('hamburger').addEventListener('click', function() {
    document.getElementById('primary-nav').classList.toggle('mobile-open');
  });

  // Order type toggle
  const toggleBtns = document.querySelectorAll('.toggle-btn');
  toggleBtns.forEach(function(btn) {
    btn.addEventListener('click', function() {
      toggleBtns.forEach(b => b.classList.remove('active'));
      this.classList.add('active');
      const mode = this.dataset.mode;
      // Visual feedback — update result items based on mode
      document.querySelectorAll('.result-item').forEach(function(item) {
        const delBadge = item.querySelector('.delivery-badge');
        if (mode === 'delivery') {
          if (!delBadge) {
            const badge = document.createElement('div');
            badge.className = 'delivery-badge';
            badge.innerHTML = '🛵 Delivery available';
            item.querySelector('.result-address').insertAdjacentElement('afterend', badge);
          }
        } else {
          if (delBadge) delBadge.remove();
        }
      });
    });
  });

  // Filter button toggle
  const filterBtn = document.getElementById('filter-btn');
  const filterPanel = document.getElementById('filter-panel');
  filterBtn.addEventListener('click', function() {
    filterPanel.classList.toggle('open');
    this.classList.toggle('active');
  });

  // Filter chips
  document.querySelectorAll('.filter-chip').forEach(function(chip) {
    chip.addEventListener('click', function() {
      this.classList.toggle('active');
    });
  });

  // Search suggestions
  const suggestions = [
    { icon: '📍', text: 'Seattle, WA' },
    { icon: '📍', text: 'Pike Place Market, Seattle, WA' },
    { icon: '📍', text: 'Capitol Hill, Seattle, WA' },
    { icon: '📍', text: 'Bellevue, WA' },
    { icon: '📍', text: 'Redmond, WA 98052' },
    { icon: '📍', text: 'Kirkland, WA 98033' },
  ];

  const input = document.getElementById('location-input');
  const suggestionsEl = document.getElementById('suggestions');

  input.addEventListener('input', function() {
    const val = this.value.trim().toLowerCase();
    if (val.length < 2) { suggestionsEl.classList.remove('visible'); return; }
    const matches = suggestions.filter(s => s.text.toLowerCase().includes(val));
    if (matches.length === 0) { suggestionsEl.classList.remove('visible'); return; }
    suggestionsEl.innerHTML = matches.map(function(s) {
      return '<div class="suggestion-item"><span class="suggestion-icon">' + s.icon + '</span>' + s.text + '</div>';
    }).join('');
    suggestionsEl.classList.add('visible');
    suggestionsEl.querySelectorAll('.suggestion-item').forEach(function(item) {
      item.addEventListener('click', function() {
        input.value = this.textContent.trim();
        suggestionsEl.classList.remove('visible');
      });
    });
  });

  document.addEventListener('click', function(e) {
    if (!e.target.closest('.search-input-wrap')) suggestionsEl.classList.remove('visible');
  });

  // Result item + map pin selection
  function selectStore(id) {
    document.querySelectorAll('.result-item').forEach(item => {
      item.classList.toggle('selected', item.dataset.id === String(id));
    });
    document.querySelectorAll('.map-pin').forEach(pin => {
      pin.classList.toggle('selected', pin.dataset.id === String(id));
    });
  }

  document.querySelectorAll('.result-item').forEach(function(item) {
    item.addEventListener('click', function() {
      selectStore(this.dataset.id);
    });
  });
  document.querySelectorAll('.map-pin').forEach(function(pin) {
    pin.addEventListener('click', function(e) {
      e.stopPropagation();
      selectStore(this.dataset.id);
      // Scroll result into view
      const resultItem = document.querySelector('.result-item[data-id="' + this.dataset.id + '"]');
      if (resultItem) resultItem.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    });
  });
</script>
